import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Welcome & Archive Pages","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/pages/welcome-archive.md","filePath":"frontend/pages/welcome-archive.md"}`),a={name:`frontend/pages/welcome-archive.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="welcome-archive-pages" tabindex="-1">Welcome &amp; Archive Pages <a class="header-anchor" href="#welcome-archive-pages" aria-label="Permalink to &quot;Welcome &amp; Archive Pages&quot;">​</a></h1><p>These are the primary public-facing Inertia components.</p><h2 id="welcome-jsx" tabindex="-1"><code>Welcome.jsx</code> <a class="header-anchor" href="#welcome-jsx" aria-label="Permalink to &quot;`Welcome.jsx`&quot;">​</a></h2><p>The dynamic homepage of TechyNews.</p><p><strong>Features:</strong></p><ul><li><strong>LCP Optimization:</strong> Uses an injected <code>&lt;link rel=&quot;preload&quot;&gt;</code> in the server-side Blade template to aggressively preload the primary Hero image. The <code>fetchpriority=&quot;high&quot;</code> attribute is applied to the first article card to ensure perfect Lighthouse scores.</li><li><strong>Suspense Loading:</strong> The <code>&lt;RagCopilot /&gt;</code> chat interface is deferred using <code>React.lazy()</code> to strip ~46KB from the initial JS bundle.</li><li><strong>Layout:</strong> A grid system displaying the <code>editorsChoice</code> article at the top, followed by recent news.</li></ul><h2 id="archive-jsx" tabindex="-1"><code>Archive.jsx</code> <a class="header-anchor" href="#archive-jsx" aria-label="Permalink to &quot;`Archive.jsx`&quot;">​</a></h2><p>Handles pagination and historical searching.</p><ul><li>Receives a paginated <code>articles</code> prop from Laravel.</li><li>Utilizes React state for client-side text filtering before falling back to backend search.</li></ul><h2 id="reelsdemo-jsx" tabindex="-1"><code>ReelsDemo.jsx</code> <a class="header-anchor" href="#reelsdemo-jsx" aria-label="Permalink to &quot;`ReelsDemo.jsx`&quot;">​</a></h2><p>The full-screen, vertical public news feed served at <code>/demo-reels</code>.</p><ul><li>Uses scroll snapping, article imagery, TL;DR highlights, inline actions, and interspersed ad slides.</li><li>Keeps the editorial headline and TL;DR display scale on desktop (<code>md</code> and above), while applying a compact type scale and spacing on mobile so the content does not overwhelm the viewport.</li><li>Comment actions expose accessible button labels for reliable keyboard and E2E interaction.</li></ul>',12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};